begin;
select plan(11);
select is((select count(*) from public.scenario_table_pressure_routes where scenario_version_id='e0000000-0000-0000-0000-000000000015'),5::bigint,'one pressure route per source');
select is((select count(*) from public.scenario_table_pressure_routes where source_table_number=target_table_number),0::bigint,'pressure route source differs from target');
select is((select string_agg(source_table_number||'>'||target_table_number,',' order by source_table_number) from public.scenario_table_pressure_routes where scenario_version_id='e0000000-0000-0000-0000-000000000015'),'1>3,2>4,3>5,4>1,5>2','TEST01 pressure routes are deterministic');
select ok(not has_table_privilege('authenticated','public.scenario_table_pressure_routes','SELECT'),'pressure routes are not directly readable');
select throws_ok($$update public.scenario_table_pressure_routes set instruction='changed' where id='f0000000-0000-0000-0000-000000000191'$$,'P0001','PUBLISHED_SCENARIO_IMMUTABLE','published pressure route is immutable');
select throws_ok($$delete from public.scenario_table_pressure_routes where id='f0000000-0000-0000-0000-000000000191'$$,'P0001','PUBLISHED_SCENARIO_IMMUTABLE','published pressure route cannot be deleted');
insert into auth.users(id,aud,role,email,is_anonymous) values ('00000000-0000-0000-0000-000000000519','authenticated','authenticated','pressure-player@example.test',true),('00000000-0000-0000-0000-000000000520','authenticated','authenticated','pressure-staff@example.test',false);
insert into public.staff_members(id,auth_user_id,display_name,active) values ('40000000-0000-0000-0000-000000000519','00000000-0000-0000-0000-000000000520','Pressure Staff',true);
insert into public.events(id,name) values ('10000000-0000-0000-0000-000000000519','Pressure event');
insert into public.games(id,event_id,code,lifecycle,narrative_phase,scenario_version_id) values ('a0000000-0000-0000-0000-000000000519','10000000-0000-0000-0000-000000000519','PRESSURE-TEST','live','pressure','e0000000-0000-0000-0000-000000000015');
insert into public.game_tables(id,game_id,table_number) values ('b0000000-0000-0000-0000-000000000519','a0000000-0000-0000-0000-000000000519',1);
insert into public.players(id,game_id,auth_user_id,table_id,seat_number,nickname) values ('20000000-0000-0000-0000-000000000519','a0000000-0000-0000-0000-000000000519','00000000-0000-0000-0000-000000000519','b0000000-0000-0000-0000-000000000519',1,'Pressure Player');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000519',true); select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000519","role":"authenticated","is_anonymous":true}',true);
select is((select pressure_title from public.get_my_player_state('PRESSURE-TEST')),'Mettete sotto pressione','Player receives pressure cue');
select is((select pressure_target_table_number from public.get_my_player_state('PRESSURE-TEST')),3,'Player receives own target');
select is((select pressure_route_title from public.get_my_player_state('PRESSURE-TEST')),'La domanda scomoda','Player receives own route only');
select is((select count(*) from public.get_my_player_state('PRESSURE-TEST')),1::bigint,'Player cannot obtain other routes');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000520',true); select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000520","role":"authenticated","is_anonymous":false}',true);
select is((select count(*) from public.get_staff_game_pressure_routes('PRESSURE-TEST')),5::bigint,'Staff sees all pressure routes');
select * from finish(); rollback;
